import numpy as np
from scirel.inference import solve_direct_anisotropic_inversion
R, Z = np.meshgrid([0.2, 0.4], [-0.1, 0.1])
def solve(state):
    return {'converged': True, 'failure_reason': None, 'profiles': {'p_perp': np.full_like(state['r_grid'], state['params']['p0'])}}
def diagnose(state):
    return {'thomson': {'p_perp': state['equilibrium']['profiles']['p_perp']}}
r = solve_direct_anisotropic_inversion(initial_params={'p0': 1.0}, bounds={'p0': (0.1, 10.0)}, method='least_squares', fit_keys=['p0'], solver_config={'r_grid': R, 'z_grid': Z}, observations={'thomson': {'p_perp': {'values': np.full_like(R, 4.0), 'sigma': 1.0}}}, equilibrium_solver=solve, diagnostic_evaluator=diagnose)
assert r['converged'] and abs(r['best_parameters']['p0'] - 4.0) < 1e-6
assert r['chi2'] < 1e-10
